FONTS = [{'path': 'shared/vendor/fontawesome/webfonts/fa-brands-400.woff2', 'oldUrl': 'https://cdn.jsdelivr.net/npm/@fortawesome/fontawesome-free@6.4.0/webfonts/fa-brands-400.woff2', 'bytes': 108020, 'sha256': '748332090c4b8e20f95d0ff59f0be20fa9c889359d3b36d4b886d73376054207'}, {'path': 'shared/vendor/fontawesome/webfonts/fa-solid-900.woff2', 'oldUrl': 'https://cdn.jsdelivr.net/npm/@fortawesome/fontawesome-free@6.4.0/webfonts/fa-solid-900.woff2', 'bytes': 150124, 'sha256': '7152a6933ee3d690ec2af3d09da9d701723d16aa3410a6d80f28ff8866f3b880'}, {'path': 'shared/vendor/fontawesome/webfonts/fa-regular-400.woff2', 'oldUrl': 'https://cdn.jsdelivr.net/npm/@fortawesome/fontawesome-free@6.4.0/webfonts/fa-regular-400.woff2', 'bytes': 24948, 'sha256': '8e7e5ea1b15f62ab14dbd41768e8fbcd21cc859a4ea5da812457ee714299fb35'}]

for name, text in FILES.items():
    target=Path(name)
    if target.is_absolute() or '..' in target.parts: raise ValueError('unsafe path')
    target.parent.mkdir(parents=True,exist_ok=True)
    target.write_text(text,encoding='utf-8')

def copy(item):
    target=Path(item['path'])
    if target.is_absolute() or '..' in target.parts: raise ValueError('unsafe path')
    expected=item['sha256']
    if target.exists() and hashlib.sha256(target.read_bytes()).hexdigest()==expected:return
    p=urllib.parse.urlsplit(item['oldUrl'])
    if p.scheme!='https' or p.hostname not in {'github.com','raw.githubusercontent.com','i.postimg.cc','cdn.jsdelivr.net'}:raise ValueError('unexpected source')
    if p.hostname=='github.com':
        parts=p.path.split('/')
        if parts[3]!='blob':raise ValueError('unexpected source path')
        url='https://raw.githubusercontent.com/'+'/'.join(parts[1:3]+parts[4:])
    else:url=urllib.parse.urlunsplit((p.scheme,p.netloc,p.path,'',''))
    url=urllib.parse.quote(url,safe=':/%?=&@')
    for attempt in range(3):
        try:
            with urllib.request.urlopen(urllib.request.Request(url,headers={'User-Agent':'Hogsmeade-project-import'}),timeout=60) as response:content=response.read()
            if len(content)!=item['bytes'] or hashlib.sha256(content).hexdigest()!=expected:raise ValueError('source checksum changed: '+str(target))
            target.parent.mkdir(parents=True,exist_ok=True)
            target.write_bytes(content)
            return
        except Exception:
            if attempt==2:raise
            time.sleep(attempt+1)

items=json.loads(Path('migration/image-links.json').read_text())['images']+FONTS
with concurrent.futures.ThreadPoolExecutor(max_workers=6) as pool:
    for i,_ in enumerate(pool.map(copy,items),1):
        if i%20==0 or i==len(items):print('verified',i,'of',len(items),flush=True)
print('Project ready:',len(FILES),'text files and',len(items),'verified binary files',flush=True)
